from dataclasses import dataclass


@dataclass(frozen=True)
class Point:
    x: float
    y: float

    def distance_to(self, other):
        dx = self.x - other.x
        dy = self.y - other.y
        return (dx * dx + dy * dy) ** 0.5


def point_distance(p1, p2):
    if p1 is None or p2 is None:
        return None
    if len(p1) != 2 or len(p2) != 2:
        return None
    first = Point(float(p1[0]), float(p1[1]))
    second = Point(float(p2[0]), float(p2[1]))
    return round(first.distance_to(second), 6)
